def get_all_controls():
    controls = []
    for function_name, subcategories in NIST_CSF.items():
        for sc in subcategories:
            sc["function"] = function_name
            controls.append(sc)
    return controls

def assess(function_name=None):
    controls = NIST_CSF.get(function_name, []) if function_name else get_all_controls()
    return controls

if __name__ == "__main__":
    total = sum(len(v) for v in NIST_CSF.values())
    print(f"NIST CSF 2.0 — {total} controls across {len(NIST_CSF)} functions\n")
    for func, controls in NIST_CSF.items():
        print(f"  {func.upper()} ({len(controls)} controls)")
        for c in controls:
            print(f"    {c['id']:12s} {c['title']}")
        print()
